import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.Bzl7znUD.js";const m=JSON.parse('{"title":"The model — files, approval, agents","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/model.md","filePath":"explanation/model.md"}'),s={name:"explanation/model.md"};function i(n,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="the-model-—-files-approval-agents" tabindex="-1">The model — files, approval, agents <a class="header-anchor" href="#the-model-—-files-approval-agents" aria-label="Permalink to &quot;The model — files, approval, agents&quot;">​</a></h1><h2 id="files-are-a-projection-not-the-state" tabindex="-1">Files are a projection, not the state <a class="header-anchor" href="#files-are-a-projection-not-the-state" aria-label="Permalink to &quot;Files are a projection, not the state&quot;">​</a></h2><p>Git materializes a working tree because POSIX tools need paths. Sturn keeps the tree <em>virtual</em>: <code>ws_read</code> serves blob contents straight from the object database — no checkout, no index, no lock.</p><p>When something genuinely needs real files:</p><ul><li><code>sturn exec --ws w -- cmd</code> — hydrate the ws view (tip + uncommitted ops) to tmpfs, run, discard</li><li><code>sturn mount w /dir --rw</code> — live FUSE filesystem; edits buffer per-open and become Write/Delete/Rename ops on release</li><li><code>--writeback</code> on <code>exec</code>/<code>hydrate</code> — dir diffs flow back as ops</li></ul><p>Agents aren&#39;t filesystem-deprived — <code>ws_read/ws_write/ws_glob/ ws_grep</code> are the same file primitives harnesses already use; the backend is virtualized, not the interaction.</p><h2 id="approval-without-the-pr-cliff" tabindex="-1">Approval without the PR cliff <a class="header-anchor" href="#approval-without-the-pr-cliff" aria-label="Permalink to &quot;Approval without the PR cliff&quot;">​</a></h2><p>Every op is content-addressed and streams through the WAL. A reviewer emits <code>review &lt;op-id&gt; approve|reject</code> — itself a signed, attributed op. With <code>[review] require = true</code>, <code>snap</code> refuses unreviewed tree ops and names their ids — the gate exists, but verdicts stream <em>per-op before commit time</em> instead of one giant diff at the end. PRs become a packaging format, not the gate.</p><h2 id="agents-review-agents" tabindex="-1">Agents review agents <a class="header-anchor" href="#agents-review-agents" aria-label="Permalink to &quot;Agents review agents&quot;">​</a></h2><p>A verdict is just an op — any actor appends it. Intended topology: fast writers produce ops → a senior agent or human watches <code>subs ops|review</code> and emits verdicts → gated <code>snap</code> lands only approved work. Humans spot-check the stream instead of serializing merges.</p>',10)])])}const f=t(s,[["render",i]]);export{m as __pageData,f as default};
